# Import these classes lazily to avoid circular imports
def _get_collection_class(name):
    """Get collection class lazily to avoid circular imports"""
    from dask.dataframe.dask_expr._collection import DataFrame, Index, Scalar, Series, FrameBase
    if name == "DataFrame":
        return DataFrame
    elif name == "Series":
        return Series
    elif name == "Index":
        return Index
    elif name == "Scalar":
        return Scalar
    elif name == "_Frame":
        return FrameBase
    else:
        raise ValueError(f"Unknown collection class: {name}")

